import SwiftUI

/// Bone and Signal, synchronized by sync_colors.py from the canonical
/// design-system/tokens/native-colors.json. Legacy ember/tide identifiers
/// are compatibility aliases for black actions and blue links respectively.
///
/// Each token is backed by a `.colorset` (light + dark sRGB components) in
/// every target's own `Assets.xcassets` — generated by a one-off script from
/// the same hex values in `tokens.json`, rather than a `UIColor`-dynamic-
/// provider lookup. `UIColor`/`UITraitCollection` don't exist on watchOS, and
/// this file is compiled into the iOS app, the watch app, *and* the watch
/// complication extension, so it has to stay UIKit-free. `Color(_:)` by name
/// is plain SwiftUI and resolves light/dark on every platform that ships it.
enum SerasonaColor {
    // MARK: Surfaces
    static let surfaceCanvas = Color("surfaceCanvas")
    static let surfaceRaised = Color("surfaceRaised")
    static let surfaceSunken = Color("surfaceSunken")
    static let surfaceInverse = Color("surfaceInverse")
    static let surfaceEmberSoft = Color("surfaceEmberSoft")
    static let surfaceTideSoft = Color("surfaceTideSoft")
    static let overlayScrim = Color("overlayScrim")

    // MARK: Borders
    static let borderHairline = Color("borderHairline")
    static let borderStrong = Color("borderStrong")

    // MARK: Ink
    static let inkStrong = Color("inkStrong")
    static let inkBody = Color("inkBody")
    static let inkMuted = Color("inkMuted")
    static let inkInverse = Color("inkInverse")
    static let inkOnEmber = Color("inkOnEmber")
    static let inkOnTide = Color("inkOnTide")

    // MARK: Brand
    static let ember = Color("ember")
    static let emberHover = Color("emberHover")
    static let emberPress = Color("emberPress")
    static let tide = Color("tide")
    static let tideHover = Color("tideHover")

    // MARK: Metrics (fatigue / stress / hydration triad used in dials & sparklines)
    static let metricFatigue = Color("metricFatigue")
    static let metricStress = Color("metricStress")
    static let metricHydration = Color("metricHydration")
    static let metricFatigueSoft = Color("metricFatigueSoft")
    static let metricStressSoft = Color("metricStressSoft")
    static let metricHydrationSoft = Color("metricHydrationSoft")

    // MARK: Result bands (NORMAL/LOW/MODERATE/ELEVATED) — see SignalBand.swift
    static let stateClear = bandNormal
    static let stateWatch = Color("stateWatch")
    static let stateStrained = Color("stateStrained")
    static let stateClearSoft = surfaceSunken
    static let stateWatchSoft = Color("stateWatchSoft")
    static let stateStrainedSoft = Color("stateStrainedSoft")

    // MARK: Band colors as used by signal-band.ts (NORMAL/LOW/MODERATE/ELEVATED/INCONCLUSIVE)
    static let bandNormal = Color("bandNormal")
    static let bandLow = Color("bandLow")
    static let bandModerate = Color("bandModerate")
    static let bandElevated = Color("bandElevated")
    static let bandInconclusive = Color("bandInconclusive")

    static let waveformActive = ember
    static let waveformIdle = Color("waveformIdle")
    static let chartGrid = borderHairline
    static let chartBand = Color("chartBand")

    /// `shadow-ember` — the one coloured shadow in the system, reserved for
    /// the record control. Not a `.colorset` since it's only ever used as an
    /// opacity-adjusted shadow tint, never a flat fill.
    static let shadowEmberTint = Color("inkStrong")
}

/// `space-*` — 4px base scale.
enum SerasonaSpace {
    static let s0: CGFloat = 0
    static let s1: CGFloat = 4
    static let s2: CGFloat = 8
    static let s3: CGFloat = 12
    static let s4: CGFloat = 16
    static let s5: CGFloat = 20
    static let s6: CGFloat = 24
    static let s7: CGFloat = 28
    static let s8: CGFloat = 32
    static let s10: CGFloat = 40
}

/// `radius-*` — Serasona rounds generously; a right angle is reserved for
/// chart plot areas and full-bleed media.
enum SerasonaRadius {
    static let xs: CGFloat = 4
    static let sm: CGFloat = 8
    static let md: CGFloat = 12
    static let lg: CGFloat = 18
    static let xl: CGFloat = 28
    static let xxl: CGFloat = 40
    static let full: CGFloat = 9999
}
